 private final android.content.BroadcastReceiver usbReceiver=new android.content.BroadcastReceiver(){public void onReceive(Context c,Intent i){if(web!=null)web.postDelayed(()->{if(ready&&!isFinishing())web.evaluateJavascript("window.dispatchEvent(new Event('morphStorageChanged'))",null);},400);}};private boolean usbReceiverRegistered;private volatile boolean kidsPlaying;
