 private void requestMaintenance(){runOnUiThread(()->{if(hasWindowFocus())AppMaintenance.show(this);else{pendingMaintenance=true;startActivity(new Intent(this,TvActivity.class).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT));}});}
 private void guarded(String id,Runnable action){runOnUiThread(()->{Runnable proceed=()->{if(AppLocks.locked(this,id)&&!hasWindowFocus()){pendingLockId=id;pendingLockAction=action;startActivity(new Intent(this,TvActivity.class).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT));}else AppLocks.guard(this,id,action);};if(ready&&web!=null&&!id.equals("local.tvmorph.tv.prayer"))web.evaluateJavascript("!(window.ClearTV&&ClearTV.Prayer&&ClearTV.Prayer.allowLaunch)||ClearTV.Prayer.allowLaunch()",result->{if(!"false".equals(result))proceed.run();else android.widget.Toast.makeText(this,UiSettings.text(this,"استراحة الصلاة مفعّلة. حاول بعد انتهاء العدّ التنازلي.","Prayer break is active. Retry after the countdown."),1).show();});else proceed.run();});}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)HomeOverrideService.settled(this);if(focus&&pendingMaintenance){pendingMaintenance=false;AppMaintenance.show(this);}if(focus&&pendingLockAction!=null){String id=pendingLockId;Runnable action=pendingLockAction;pendingLockId=null;pendingLockAction=null;guarded(id,action);}}
