 @Override protected void onPause(){if(web!=null)web.evaluateJavascript("if(window.ClearTV){if(ClearTV.Kids)ClearTV.Kids.close();if(ClearTV.Prayer)ClearTV.Prayer.setVisible(false);}",null);super.onPause();}
 @Override protected void onResume(){super.onResume();if(web!=null)web.evaluateJavascript("window.dispatchEvent(new Event('morphStorageChanged'))",null);ParentalTimer.window(this,getPackageName());if(web!=null)web.evaluateJavascript("if(window.ClearTV&&ClearTV.Prayer)ClearTV.Prayer.setVisible(true)",null);startPhoneLink();TvUpdater.resume(this);if(web!=null)web.evaluateJavascript("if(window.MorphLocale)MorphLocale.set("+JSONObject.quote(UiSettings.language(this))+")",null);}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.getBooleanExtra("showStartup",false)&&ready){intent.removeExtra("showStartup");StartupSettings.show(this);}if(intent.hasCategory(Intent.CATEGORY_HOME)&&ready)web.evaluateJavascript("if(window.ClearTV&&ClearTV.Remote)ClearTV.Remote.key('HOME')",null);if(intent.getBooleanExtra("openPlay",false)){if(ready)guarded("local.tvmorph.tv.play",()->startActivity(new Intent(this,IptvActivity.class)));else pendingPlay=true;}}
 @Override public void onBackPressed(){web.evaluateJavascript("if(window.ClearTV&&ClearTV.Remote)ClearTV.Remote.key('RETURN');else if(window.ClearTV)ClearTV.back()",null);}
 @Override protected void onDestroy(){ParentalTimer.leave("local.tvmorph.tv.kids");if(usbReceiverRegistered){try{unregisterReceiver(usbReceiver);}catch(RuntimeException ignored){}usbReceiverRegistered=false;}if(textEntry!=null){textEntry.setOnDismissListener(null);textEntry.dismiss();textEntry=null;}PhoneLinkServer.detach(this);serverRunning=PhoneLinkServer.running();web.destroy();super.onDestroy();}
 @Override public boolean dispatchKeyEvent(android.view.KeyEvent event){
  if(event.getKeyCode()==android.view.KeyEvent.KEYCODE_DPAD_CENTER&&web!=null&&web.hasFocus()){
   if(event.getAction()==android.view.KeyEvent.ACTION_DOWN||event.getAction()==android.view.KeyEvent.ACTION_UP){String type=event.getAction()==android.view.KeyEvent.ACTION_DOWN?"keydown":"keyup";web.evaluateJavascript("(function(){var e=new Event('"+type+"',{bubbles:true,cancelable:true});Object.defineProperty(e,'keyCode',{value:13});Object.defineProperty(e,'repeat',{value:"+(event.getRepeatCount()>0)+"});(document.activeElement||document).dispatchEvent(e);})()",null);}return true;
  }return super.dispatchKeyEvent(event);
 }

